Debounce delay fire. Wait until user stop typing, then call API. Add abort so stale response not overwrite new one.

**React hook + component (TypeScript):**

```tsx
import { useEffect, useState } from "react";

function useDebounce<T>(value: T, delay = 300): T {
  const [debounced, setDebounced] = useState(value);

  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id); // reset timer on each keystroke
  }, [value, delay]);

  return debounced;
}

export function Search() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState<unknown[]>([]);
  const debouncedQuery = useDebounce(query, 300);

  useEffect(() => {
    if (!debouncedQuery.trim()) {
      setResults([]);
      return;
    }

    const controller = new AbortController();

    fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then((res) => res.json())
      .then(setResults)
      .catch((err) => {
        if (err.name !== "AbortError") console.error(err);
      });

    return () => controller.abort(); // cancel in-flight req if query change
  }, [debouncedQuery]);

  return (
    <input
      value={query}
      onChange={(e) => setQuery(e.target.value)}
      placeholder="Search..."
    />
  );
}
```

**Vanilla JS version:**

```js
function debounce(fn, delay = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

const input = document.querySelector("#search");
let controller;

const search = async (q) => {
  controller?.abort();
  controller = new AbortController();
  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(q)}`, {
      signal: controller.signal,
    });
    render(await res.json());
  } catch (e) {
    if (e.name !== "AbortError") console.error(e);
  }
};

input.addEventListener("input", debounce((e) => search(e.target.value), 300));
```

Notes:
- Input state (`query`) update immediately → typing stay responsive. Only API call delayed.
- 300ms typical. 200–500ms range fine.
- Skip empty query → no wasted call.
